import platform
import psutil

def get_system_info():
    # OS Information
    os_info = {
        "OS Type": platform.system(),
        "OS Version": platform.version(),
        "OS Release": platform.release(),
        "Architecture": platform.architecture()[0]
    }

    # CPU Information
    cpu_info = {
        "CPU Count": psutil.cpu_count(logical=True),
        "CPU Frequency (MHz)": psutil.cpu_freq().current
    }

    # Memory Information
    memory_info = psutil.virtual_memory()
    memory_stats = {
        "Total Memory (GB)": memory_info.total / (1024 ** 3),
        "Available Memory (GB)": memory_info.available / (1024 ** 3)
    }

    # Combine all information
    system_info = {
        "OS Information": os_info,
        "CPU Information": cpu_info,
        "Memory Information": memory_stats
    }

    return system_info

# Print the system information
info = get_system_info()
for category, details in info.items():
    print(f"{category}:")
    for key, value in details.items():
        print(f"  {key}: {value}")

import javax.swing.*;
import java.awt.event.*;
import java.io.*;

public class Notepad {
    public static void main(String[] args) {
        JFrame frame = new JFrame("Notepad");
        JTextArea textArea = new JTextArea();
        JScrollPane scrollPane = new JScrollPane(textArea);

        JMenuBar menuBar = new JMenuBar();
        JMenu fileMenu = new JMenu("File");

        JMenuItem openItem = new JMenuItem("Open");
        JMenuItem saveItem = new JMenuItem("Save");

        openItem.addActionListener(e -> {
            JFileChooser fileChooser = new JFileChooser();
            if (fileChooser.showOpenDialog(frame) == JFileChooser.APPROVE_OPTION) {
                File file = fileChooser.getSelectedFile();
                try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
                    textArea.read(reader, null);
                } catch (IOException ex) {
                    ex.printStackTrace();
                }
            }
        });

        saveItem.addActionListener(e -> {
            JFileChooser fileChooser = new JFileChooser();
            if (fileChooser.showSaveDialog(frame) == JFileChooser.APPROVE_OPTION) {
                File file = fileChooser.getSelectedFile();
                try (BufferedWriter writer = new BufferedWriter(new FileWriter(file))) {
                    textArea.write(writer);
                } catch (IOException ex) {
                    ex.printStackTrace();
                }
            }
        });

        fileMenu.add(openItem);
        fileMenu.add(saveItem);
        menuBar.add(fileMenu);

        frame.setJMenuBar(menuBar);
        frame.add(scrollPane);
        frame.setSize(600, 400);
        frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        frame.setVisible(true);
    }
}

import PyPDF2

def read_pdf_metadata(file_path):
    try:
        # Open the PDF file
        with open(file_path, 'rb') as file:
            # Create a PDF reader object
            pdf_reader = PyPDF2.PdfReader(file)

            # Get the document metadata
            metadata = pdf_reader.metadata

            # Print out the metadata
            if metadata:
                print("PDF Metadata:")
                for key, value in metadata.items():
                    print(f"{key}: {value}")
            else:
                print("No metadata found in the PDF file.")

    except Exception as e:
        print(f"An error occurred: {e}")

