import platform
import subprocess

def is_service_running(service_name):
    system = platform.system()

    if system == "Windows":
        # Command to check services on Windows
        cmd = f'sc query "{service_name}"'
        try:
            output = subprocess.check_output(cmd, shell=True, stderr=subprocess.STDOUT, text=True)
            if "RUNNING" in output:
                return True
            else:
                return False
        except subprocess.CalledProcessError:
            return False

    elif system == "Linux":
        # Command to check services on Linux
        cmd = f'systemctl is-active --quiet {service_name}'
        try:
            subprocess.check_call(cmd, shell=True)
            return True
        except subprocess.CalledProcessError:
            return False

    else:
        raise NotImplementedError(f"Service check not implemented for platform: {system}")

# Example usage
service_name = "UpdateService"  # Adjust as needed for your specific service
if is_service_running(service_name):
    print(f"The service '{service_name}' is running.")
else:
    print(f"The service '{service_name}' is not running.")

